-- =====================================================================
-- PROPOSED (not applied): Phase 1 server-side input validation for Dorly.
-- Target: Supabase project database, PostgreSQL 17 (works on PostgreSQL 12+; does NOT use CREATE OR REPLACE TRIGGER).
-- Media URLs are only accepted from Supabase project sayqxowybxpqmqfshmqk (regenerate with --project-ref=<ref> for staging),
-- inside the listing owner's folder and the listing's own folder.
-- Adds a second BEFORE trigger "dorly_validate" on every dorly_* table that holds app data.
-- Triggers of the same timing fire in name order, so it runs AFTER the existing "dorly_guard"
-- (which rewrites protected fields) and checks the final row. The guard triggers are not touched.
-- It applies to everyone (sellers, customers, admins, service role): only well-formed data is stored.
-- Rejected writes fail with SQLSTATE 23514 (check_violation) and message 'dorly: invalid <field>'.
-- No existing row is read or modified. Existing rows are only re-checked if they are updated later.
--
-- Safe to run more than once: functions use CREATE OR REPLACE, triggers are dropped (if present) and
-- re-created inside ONE transaction, so there is never a moment without validation and a failure
-- anywhere rolls everything back. The checks at the start and end abort the transaction if the
-- database is not in the expected state. Rollback: rollback/rollback_phase1_input_validation.sql
-- Run it as one script (SQL editor or psql). Generated by tools/gen_validation_sql.py — edit the rules there.
-- =====================================================================
begin;
set local lock_timeout = '5s';          -- never queue behind a long transaction while holding table locks

-- ---------- pre-check: the objects this migration relies on exist ----------
do $chk$
declare t text;
begin
  if to_regnamespace('dorly_internal') is null then raise exception 'pre-check: schema dorly_internal missing'; end if;
  foreach t in array array['dorly_listings','dorly_sellers','dorly_inquiries','dorly_complaints','dorly_verifs','dorly_audit','dorly_seller_private','dorly_listing_private']::text[] loop
    if to_regclass('public.' || t) is null then raise exception 'pre-check: table % missing', t; end if;
  end loop;
  foreach t in array array['dorly_listings','dorly_sellers','dorly_inquiries','dorly_complaints','dorly_verifs','dorly_seller_private','dorly_listing_private']::text[] loop
    if not exists (select 1 from pg_trigger where tgrelid = ('public.' || t)::regclass and tgname = 'dorly_guard' and not tgisinternal) then
      raise exception 'pre-check: guard trigger dorly_guard missing on %', t;
    end if;
  end loop;
end $chk$;

-- owner: the listing's owner (auth uid) for dorly_listings, so media paths can be tied to it; null elsewhere
create or replace function dorly_internal.dorly_problem(tbl text, rid text, d jsonb, owner text) returns text
language sql immutable set search_path = pg_catalog, pg_temp as $$
  select case when rid is null or rid !~ '^[A-Za-z0-9_-]{1,64}$' then 'id'
  when jsonb_typeof(d) is distinct from 'object' then 'data'
  when pg_column_size(d) > 100000 then 'data size'
  when tbl = 'dorly_listings' then (case when not ((case when (d ? 'seller' and jsonb_typeof(d->'seller') <> 'null') then (jsonb_typeof(d->'seller')='string' and (d->>'seller') ~ '^[A-Za-z0-9_-]{1,64}$') else false end)) then 'seller' when not ((case when (d ? 'gen' and jsonb_typeof(d->'gen') <> 'null') then ((jsonb_typeof(d->'gen')='number' and (d->>'gen')::numeric between 1 and 40 and (d->>'gen')::numeric = trunc((d->>'gen')::numeric)) or (jsonb_typeof(d->'gen')='string' and ((d->>'gen') = any(array['2G','3G','3GS','4','4S','5','5c','5s','6','6s','7','8','SE','X','XR','XS','11','12','13','14','15','16','17','16e','17e','Air']::text[]) or (d->>'gen') ~ '^[0-9]{1,2}$'))) else false end)) then 'gen' when not ((case when (d ? 'variant' and jsonb_typeof(d->'variant') <> 'null') then (jsonb_typeof(d->'variant')='string' and (d->>'variant') = any(array['','Plus','Pro','Pro Max','mini','Max','e','2016','2020','2022']::text[])) else true end)) then 'variant' when not ((case when (d ? 'storage' and jsonb_typeof(d->'storage') <> 'null') then (jsonb_typeof(d->'storage')='string' and (d->>'storage') ~ '^[0-9]{1,4}(GB|TB)$') else false end)) then 'storage' when not ((case when (d ? 'battery' and jsonb_typeof(d->'battery') <> 'null') then (jsonb_typeof(d->'battery')='number' and (d->>'battery')::numeric between 0 and 100 and (d->>'battery')::numeric = trunc((d->>'battery')::numeric)) else false end)) then 'battery' when not ((case when (d ? 'price' and jsonb_typeof(d->'price') <> 'null') then (jsonb_typeof(d->'price')='number' and (d->>'price')::numeric between 1000 and 300000 and (d->>'price')::numeric = trunc((d->>'price')::numeric)) else false end)) then 'price' when not ((case when (d ? 'cond' and jsonb_typeof(d->'cond') <> 'null') then (jsonb_typeof(d->'cond')='string' and (d->>'cond') = any(array['excellent','vgood','good']::text[])) else false end)) then 'cond' when not ((case when (d ? 'status' and jsonb_typeof(d->'status') <> 'null') then (jsonb_typeof(d->'status')='str