/dorly-public/' || coalesce(owner, '[0-9a-f-]{36}') || '/listings/' || rid || '/[A-Za-z0-9_-]{1,40}\.(jpg|png|webp)$')))) else true end)) then 'photos' when not ((case when (d ? 'shots' and jsonb_typeof(d->'shots') <> 'null') then (jsonb_typeof(d->'shots')='object' and not exists (select 1 from jsonb_each(d->'shots') e where not (e.key = any(array['battery','about','storage','parts']::text[]) and (jsonb_typeof(e.value)='null' or (jsonb_typeof(e.value)='string' and (e.value#>>'{}') ~ ('^sbp:' || coalesce(owner, '[0-9a-f-]{36}') || '/listings/' || rid || '/[A-Za-z0-9_-]{1,40}\.(jpg|png|webp)$')))))) else true end)) then 'shots' when not ((case when (d ? 'form' and jsonb_typeof(d->'form') <> 'null') then (jsonb_typeof(d->'form')='object') else true end)) then 'form' when not ((case when (d ? 'pay' and jsonb_typeof(d->'pay') <> 'null') then (jsonb_typeof(d->'pay')='object' and coalesce(d->'pay'->>'status','unpaid') in ('unpaid','paid')) else true end)) then 'pay' else null end)
